81: // Open opens or creates a SQLite job database at path, applying WAL mode, busy_timeout,
82: // and table initialization.
83: func Open(path string, opts ...Option) (*Store, error) {
84: 	if path == "" {
85: 		return nil, fmt.Errorf("database path cannot be empty")
86: 	}
87: 
88: 	// Create parent directory if needed (for file-based database)
89: 	if path != ":memory:" && !strings.HasPrefix(path, "file::memory:") {
90: 		dir := filepath.Dir(path)
91: 		if err := os.MkdirAll(dir, 0755); err != nil {
92: 			return nil, fmt.Errorf("creating database directory %s: %w", dir, err)
93: 		}
94: 	}
95: 
96: 	store := &Store{
97: 		maxAttempts:          DefaultMaxAttempts,
98: 		defaultLeaseDuration: DefaultLeaseDuration,
99: 		busyTimeout:          DefaultBusyTimeout,
100: 	}
101: 	for _, opt := range opts {
102: 		opt(store)
103: 	}
104: 
105: 	busyTimeoutMs := int(store.busyTimeout.Milliseconds())
106: 	if busyTimeoutMs <= 0 {
107: 		busyTimeoutMs = 5000
108: 	}
109: 
110: 	dsn := path
111: 	sep := "?"
112: 	if strings.Contains(dsn, "?") {
113: 		sep = "&"
114: 	}
115: 	dsn = fmt.Sprintf("%s%s_pragma=busy_timeout(%d)&_pragma=journal_mode(WAL)&_pragma=foreign_keys(1)", dsn, sep, busyTimeoutMs)
116: 
117: 	db, err := sql.Open("sqlite", dsn)
118: 	if err != nil {
119: 		return nil, fmt.Errorf("opening sqlite database: %w", err)
120: 	}
121: 
122: 	// Enforce WAL mode and busy_timeout explicitly on connection
123: 	if _, err := db.Exec("PRAGMA journal_mode = WAL;"); err != nil {
124: 		_ = db.Close()
125: 		return nil, fmt.Errorf("setting journal_mode to WAL: %w", err)
126: 	}
127: 	if _, err := db.Exec(fmt.Sprintf("PRAGMA busy_timeout = %d;", busyTimeoutMs)); err != nil {
128: 		_ = db.Close()
129: 		return nil, fmt.Errorf("setting busy_timeout: %w", err)
130: 	}
131: 
132: 	if err := InitSchema(db); err != nil {
133: 		_ = db.Close()
134: 		return nil, fmt.Errorf("initializing schema: %w", err)
135: 	}
136: 
137: 	store.db = db
138: 	return store, nil
139: }
