177: // Enqueue inserts a new job into the job table.
178: // If an idempotency key is provided and a job with that key already exists,
179: // Enqueue returns the existing job without error (SPEC §4.3: "so duplicates are no-ops").
180: func (s *Store) Enqueue(ctx context.Context, job *Job) (*Job, error) {
181: 	if job == nil {
182: 		return nil, fmt.Errorf("%w: job cannot be nil", ErrInvalidJob)
183: 	}
184: 	if !job.Kind.Valid() {
185: 		return nil, fmt.Errorf("%w: invalid kind %q", ErrInvalidJob, job.Kind)
186: 	}
187: 
188: 	// Deduplication check via idempotency key
189: 	if job.IdempotencyKey != "" {
190: 		existing, err := s.GetByIdempotencyKey(ctx, job.IdempotencyKey)
191: 		if err == nil && existing != nil {
192: 			return existing, nil
193: 		}
194: 		if err != nil && !errors.Is(err, ErrJobNotFound) {
195: 			return nil, fmt.Errorf("checking idempotency key: %w", err)
196: 		}
197: 	}
198: 
199: 	now := time.Now().UTC()
200: 	if job.ID == "" {
201: 		job.ID = ulid.Make().String()
202: 	}
203: 	if job.State == "" {
204: 		job.State = StateQueued
205: 	}
206: 	if !job.State.Valid() {
207: 		return nil, fmt.Errorf("%w: invalid state %q", ErrInvalidJob, job.State)
208: 	}
209: 	if job.CreatedAt.IsZero() {
210: 		job.CreatedAt = now
211: 	}
212: 	job.UpdatedAt = now
213: 
214: 	query := `
215: INSERT INTO jobs (
216:     id, kind, priority, idempotency_key, state, lease_expires,
217:     attempts, next_attempt_at, cost, payload, last_error, created_at, updated_at
218: ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
219: `
220: 	_, err := s.db.ExecContext(ctx, query,
221: 		job.ID,
222: 		string(job.Kind),
223: 		job.Priority,
224: 		nullString(job.IdempotencyKey),
225: 		string(job.State),
226: 		nullTime(job.LeaseExpires),
227: 		job.Attempts,
228: 		nullTime(job.NextAttemptAt),
229: 		costValue(job.Cost),
230: 		nullString(job.Payload),
231: 		nullString(job.LastError),
232: 		job.CreatedAt,
233: 		job.UpdatedAt,
234: 	)
235: 	if err != nil {
236: 		// Handle potential race on unique idempotency_key constraint
237: 		if job.IdempotencyKey != "" && strings.Contains(strings.ToLower(err.Error()), "unique") {
238: 			existing, fetchErr := s.GetByIdempotencyKey(ctx, job.IdempotencyKey)
239: 			if fetchErr == nil && existing != nil {
240: 				return existing, nil
241: 			}
242: 		}
243: 		return nil, fmt.Errorf("inserting job: %w", err)
244: 	}
245: 
246: 	return job, nil
247: }
