555: // ReclaimExpiredLeasesDetailed executes lease recovery and returns breakdown counts.
556: func (s *Store) ReclaimExpiredLeasesDetailed(ctx context.Context, now time.Time) (ReclaimResult, error) {
557: 	if now.IsZero() {
558: 		now = time.Now().UTC()
559: 	}
560: 
561: 	tx, err := s.db.BeginTx(ctx, nil)
562: 	if err != nil {
563: 		return ReclaimResult{}, fmt.Errorf("beginning reclaim transaction: %w", err)
564: 	}
565: 	defer func() {
566: 		_ = tx.Rollback()
567: 	}()
568: 
569: 	// 1. Mark jobs that exceeded max attempts as dead
570: 	deadQuery := `
571: UPDATE jobs
572: SET state = ?, lease_expires = NULL, next_attempt_at = NULL,
573:     last_error = 'lease expired: maximum attempts exceeded', updated_at = ?
574: WHERE state = 'running'
575:   AND lease_expires IS NOT NULL
576:   AND lease_expires <= ?
577:   AND attempts >= ?;
578: `
579: 	resDead, err := tx.ExecContext(ctx, deadQuery, string(StateDead), now, now, s.maxAttempts)
580: 	if err != nil {
581: 		return ReclaimResult{}, fmt.Errorf("deadening expired jobs: %w", err)
582: 	}
583: 	deadCount, err := resDead.RowsAffected()
584: 	if err != nil {
585: 		return ReclaimResult{}, fmt.Errorf("checking dead rows affected: %w", err)
586: 	}
587: 
588: 	// 2. Re-queue jobs with remaining attempts
589: 	requeueQuery := `
590: UPDATE jobs
591: SET state = ?, lease_expires = NULL, next_attempt_at = NULL, updated_at = ?
592: WHERE state = 'running'
593:   AND lease_expires IS NOT NULL
594:   AND lease_expires <= ?
595:   AND attempts < ?;
596: `
597: 	resRequeue, err := tx.ExecContext(ctx, requeueQuery, string(StateQueued), now, now, s.maxAttempts)
598: 	if err != nil {
599: 		return ReclaimResult{}, fmt.Errorf("requeuing expired jobs: %w", err)
600: 	}
601: 	requeueCount, err := resRequeue.RowsAffected()
602: 	if err != nil {
603: 		return ReclaimResult{}, fmt.Errorf("checking requeued rows affected: %w", err)
604: 	}
605: 
606: 	if err := tx.Commit(); err != nil {
607: 		return ReclaimResult{}, fmt.Errorf("committing reclaim transaction: %w", err)
608: 	}
609: 
610: 	return ReclaimResult{
611: 		Requeued: int(requeueCount),
612: 		Deadened: int(deadCount),
613: 		Total:    int(requeueCount + deadCount),
614: 	}, nil
615: }
