617: // List returns a list of jobs matching the provided filter.
618: func (s *Store) List(ctx context.Context, filter Filter) ([]Job, error) {
619: 	var query strings.Builder
620: 	query.WriteString(`
621: SELECT id, kind, priority, idempotency_key, state, lease_expires,
622:        attempts, next_attempt_at, cost, payload, last_error, created_at, updated_at
623: FROM jobs
624: WHERE 1=1
625: `)
626: 	var args []any
627: 
628: 	if filter.State != "" {
629: 		query.WriteString(" AND state = ?")
630: 		args = append(args, string(filter.State))
631: 	}
632: 	if filter.Kind != "" {
633: 		query.WriteString(" AND kind = ?")
634: 		args = append(args, string(filter.Kind))
635: 	}
636: 
637: 	query.WriteString(" ORDER BY priority DESC, created_at ASC")
638: 
639: 	if filter.Limit > 0 {
640: 		query.WriteString(" LIMIT ?")
641: 		args = append(args, filter.Limit)
642: 	}
643: 
644: 	rows, err := s.db.QueryContext(ctx, query.String(), args...)
645: 	if err != nil {
646: 		return nil, fmt.Errorf("listing jobs: %w", err)
647: 	}
648: 	defer rows.Close()
649: 
650: 	var jobs []Job
651: 	for rows.Next() {
652: 		job, err := scanJob(rows)
653: 		if err != nil {
654: 			return nil, fmt.Errorf("scanning listed job: %w", err)
655: 		}
656: 		jobs = append(jobs, *job)
657: 	}
658: 
659: 	if err := rows.Err(); err != nil {
660: 		return nil, fmt.Errorf("iterating listed jobs: %w", err)
661: 	}
662: 
663: 	return jobs, nil
664: }
